    //     SIO_MULTI_CNT->enable = false;
    // }

    mkdir("/3ds/SonicAdvance", 0755);
    ReadSaveFile("/3ds/SonicAdvance/sa2.sav");

    // Prevent the multiplayer screen from being drawn ( see core.c:EngineInit() )
    REG_RCNT = 0x8000;
    REG_KEYINPUT = 0x3FF;

    //     if (headless) {
